      { ja: "A\uFF09\u7D0D\u54C1\u65E5\u3000B\uFF09\u7D0D\u54C1\u696D\u8005\u540D\u3000C\uFF09\u652F\u6255\u3044\u65B9\u6CD5", vi: "A) Ng\xE0y giao B) T\xEAn nh\xE0 cung c\u1EA5p C) Ph\u01B0\u01A1ng th\u1EE9c thanh to\xE1n" },
      { ja: "A\uFF09\u8CDE\u5473\u671F\u9650\u3000B\uFF09\u88FD\u9020\u65E5\u3000C\uFF09\u4FDD\u7BA1\u6E29\u5EA6\u306E\u307F", vi: "Ch\u1EC9 A) H\u1EA1n s\u1EED d\u1EE5ng B) Ng\xE0y s\u1EA3n xu\u1EA5t C) Nhi\u1EC7t \u0111\u1ED9 b\u1EA3o qu\u1EA3n" }
