    chapterId: "hy-ch3",
    questionJa: "HACCP7\u539F\u5247\u306E\u300C\u2463\u30E2\u30CB\u30BF\u30EA\u30F3\u30B0\u65B9\u6CD5\u306E\u8A2D\u5B9A\u300D\u306E\u5185\u5BB9\u3068\u3057\u3066\u6B63\u3057\u3044\u3082\u306E\u306F\u3069\u308C\u304B\u3002",
    questionVi: 'N\u1ED9i dung c\u1EE7a "\u2463 Thi\u1EBFt l\u1EADp ph\u01B0\u01A1ng ph\xE1p gi\xE1m s\xE1t (Monitoring)" l\xE0 g\xEC?',
    options: [
      { ja: "\u91CD\u8981\u7BA1\u7406\u70B9\u306E\u7BA1\u7406\u5B9F\u65BD\u72B6\u6CC1\u3092\u9023\u7D9A\u7684\u307E\u305F\u306F\u76F8\u5F53\u306A\u983B\u5EA6\u3067\u78BA\u8A8D\u3059\u308B\u65B9\u6CD5\u3092\u8A2D\u5B9A\u3059\u308B\u3053\u3068", vi: "Thi\u1EBFt l\u1EADp ph\u01B0\u01A1ng ph\xE1p x\xE1c nh\u1EADn t\xECnh tr\u1EA1ng th\u1EF1c hi\u1EC7n qu\u1EA3n l\xFD t\u1EA1i \u0111i\u1EC3m qu\u1EA3n l\xFD quan tr\u1ECDng, li\xEAn t\u1EE5c ho\u1EB7c v\u1EDBi t\u1EA7n su\u1EA5t \u0111\u1EE7 d\xE0y" },
      { ja: "\u9867\u5BA2\u30A2\u30F3\u30B1\u30FC\u30C8\u3092\u5B9F\u65BD\u3059\u308B\u3053\u3068", vi: "Th\u1EF1c hi\u1EC7n kh\u1EA3o s\xE1t kh\xE1ch h\xE0ng" },
      { ja: "\u5F93\u696D\u54E1\u306E\u9762\u63A5\u3092\u304A\u3053\u306A\u3046\u3053\u3068", vi: "Ph\u1ECFng v\u1EA5n nh\xE2n vi\xEAn" },
      { ja: "\u7AF6\u5408\u5E97\u3092\u8996\u5BDF\u3059\u308B\u3053\u3068", vi: "\u0110i kh\u1EA3o s\xE1t c\u1EEDa h\xE0ng \u0111\u1ED1i th\u1EE7" }
    ],
    correctIndex: 0,
    explanationVi: "\u30E2\u30CB\u30BF\u30EA\u30F3\u30B0\u65B9\u6CD5\u306E\u8A2D\u5B9A = \u0111\u1ECBnh ra c\xE1ch th\u1EE9c \u0111\u1EC3 x\xE1c nh\u1EADn (li\xEAn t\u1EE5c ho\u1EB7c theo t\u1EA7n su\u1EA5t \u0111\u1EE7 d\xE0y) r\u1EB1ng vi\u1EC7c qu\u1EA3n l\xFD t\u1EA1i \u0111i\u1EC3m qu\u1EA3n l\xFD quan tr\u1ECDng \u0111ang \u0111\u01B0\u1EE3c th\u1EF1c hi\u1EC7n \u0111\xFAng.",
    sourceQuoteJa: "\u30E2\u30CB\u30BF\u30EA\u30F3\u30B0\u65B9\u6CD5\u306E\u8A2D\u5B9A\uFF1A\u91CD\u8981\u7BA1\u7406\u70B9\u306E\u7BA1\u7406\u306E\u5B9F\u65BD\u72B6\u6CC1\u306B\u3064\u3044\u3066\u3001\u9023\u7D9A\u7684\u53C8\u306F\u76F8\u5F53\u306A\u983B\u5EA6\u306E\u78BA\u8A8D\uFF08\u30E2\u30CB\u30BF\u30EA\u30F3\u30B0\uFF09\u3092\u3059\u308B\u305F\u3081\u306E\u65B9\u6CD5\u3092\u8A2D\u5B9A\u3059\u308B\u3053\u3068\u3002",
