    chapterId: "hy-ch4",
    questionJa: "\u8ABF\u7406\u65BD\u8A2D\u306E\u7D0D\u54C1\u53E3\u306B\u3064\u3044\u3066\u3001\u539F\u5247\u3068\u3057\u3066\u5B88\u308B\u3079\u304D\u3053\u3068\u306F\u3069\u308C\u304B\u3002",
    questionVi: "V\u1EC1 c\u1EEDa nh\u1EADn h\xE0ng c\u1EE7a c\u01A1 s\u1EDF ch\u1EBF bi\u1EBFn, nguy\xEAn t\u1EAFc c\u1EA7n tu\xE2n th\u1EE7 l\xE0 g\xEC?",
    options: [
      { ja: "24\u6642\u9593\u5E38\u306B\u958B\u653E\u3057\u3066\u304A\u304F", vi: "Lu\xF4n \u0111\u1EC3 m\u1EDF 24/24" },
      { ja: "\u642C\u5165\u6642\u4EE5\u5916\u306B\u306F\u6249\u3092\u9589\u3081\u3066\u304A\u304F", vi: "Ngo\xE0i l\xFAc nh\u1EADp h\xE0ng th\xEC lu\xF4n \u0111\xF3ng c\u1EEDa" },
      { ja: "\u65BD\u9320\u305B\u305A\u8AB0\u3067\u3082\u51FA\u5165\u308A\u3067\u304D\u308B\u3088\u3046\u306B\u3059\u308B", vi: "Kh\xF4ng kh\xF3a, \u0111\u1EC3 ai c\u0169ng ra v\xE0o \u0111\u01B0\u1EE3c" },
      { ja: "\u7D0D\u54C1\u53E3\u306F\u4E0D\u8981", vi: "Kh\xF4ng c\u1EA7n c\u1EEDa nh\u1EADn h\xE0ng" }
    ],
    correctIndex: 1,
    explanationVi: "C\u1EEDa nh\u1EADn h\xE0ng d\u1EC5 ch\u1ECBu \u1EA3nh h\u01B0\u1EDFng t\u1EEB b\u1EE5i, l\xE1 r\u1EE5ng, c\xF4n tr\xF9ng x\xE2m nh\u1EADp khi m\u1EDF \u2014 nguy\xEAn t\u1EAFc l\xE0 \u0111\xF3ng c\u1EEDa ngo\u1EA1i tr\u1EEB l\xFAc \u0111ang nh\u1EADn h\xE0ng.",
    sourceQuoteJa: "\u642C\u5165\u6642\u4EE5\u5916\u306B\u306F\u6249\u3092\u9589\u3081\u3066\u304A\u304F\u3053\u3068\u304C\u539F\u5247\u3067\u3059\u3002",
    sourcePage: 9
