    questionJa: "\u300C\u898B\u3048\u308B\u5316\u300D\u304C\u3067\u304D\u308B\u3053\u3068\u3068\u3057\u3066\u6B63\u3057\u3044\u3082\u306E\u306F\u3069\u308C\u304B\u3002",
    questionVi: "'Tr\u1EF1c quan h\xF3a' gi\xFAp l\xE0m \u0111\u01B0\u1EE3c \u0111i\u1EC1u g\xEC?",
    options: [
      { ja: "\u5F93\u696D\u54E1\u306E\u7D66\u4E0E\u3092\u4E0A\u3052\u308B\u3053\u3068", vi: "T\u0103ng l\u01B0\u01A1ng cho nh\xE2n vi\xEAn" },
      { ja: "\u98DF\u6750\u306E\u5728\u5EAB\u3092\u7BA1\u7406\u3059\u308B\u3053\u3068", vi: "Qu\u1EA3n l\xFD t\u1ED3n kho nguy\xEAn li\u1EC7u" },
      { ja: "\u63A5\u5BA2\u30DE\u30CA\u30FC\u3092\u6539\u5584\u3059\u308B\u3053\u3068", vi: "C\u1EA3i thi\u1EC7n phong c\xE1ch ph\u1EE5c v\u1EE5 kh\xE1ch" },
      { ja: "\u5371\u967A\u8A8D\u8B58\u3084\u4F5C\u696D\u5834\u306E\u6CE8\u610F\u559A\u8D77\u3092\u5206\u304B\u308A\u3084\u3059\u304F\u77E5\u3089\u305B\u308B\u3053\u3068", vi: "Truy\u1EC1n \u0111\u1EA1t d\u1EC5 hi\u1EC3u v\u1EC1 nh\u1EADn th\u1EE9c nguy hi\u1EC3m v\xE0 c\u1EA3nh b\xE1o t\u1EA1i n\u01A1i l\xE0m vi\u1EC7c" }
    ],
    correctIndex: 3,
    explanationVi: "'Tr\u1EF1c quan h\xF3a' gi\xFAp truy\u1EC1n \u0111\u1EA1t d\u1EC5 hi\u1EC3u v\u1EC1 nh\u1EADn th\u1EE9c nguy hi\u1EC3m v\xE0 c\u1EA3nh b\xE1o ch\xFA \xFD t\u1EA1i n\u01A1i l\xE0m vi\u1EC7c.",
    sourceQuoteJa: "\u300C\u898B\u3048\u308B\u5316\u300D\u306F\u5371\u967A\u8A8D\u8B58\u3084\u4F5C\u696D\u5834\u306E\u6CE8\u610F\u559A\u8D77\u3092\u5206\u304B\u308A\u3084\u3059\u304F\u77E5\u3089\u305B\u308B\u3053\u3068\u304C\u3067\u304D\u307E\u3059\u3002",
