      { ja: "\u3059\u3050\u306B\u5168\u984D\u8FD4\u91D1\u3059\u308B\u3060\u3051\u3067\u6E08\u307E\u305B\u308B", vi: "Ch\u1EC9 c\u1EA7n ho\xE0n ti\u1EC1n to\xE0n b\u1ED9 ngay l\xE0 xong" },
      { ja: "\u304A\u5BA2\u69D8\u306E\u5473\u899A\u306E\u305B\u3044\u306B\u3059\u308B", vi: "\u0110\u1ED5 l\u1ED7i cho kh\u1EA9u v\u1ECB c\u1EE7a kh\xE1ch" }
