    questionJa: "\u30EC\u30B8\u7DE0\u3081\u3067\u8AA4\u5DEE\u304C\u51FA\u308B\u3068\u3044\u3046\u3053\u3068\u306F\u4F55\u3092\u610F\u5473\u3059\u308B\u304B\u3002",
