      { ja: "\u6B63\u3057\u3044\u3002\u3053\u306E2\u9805\u76EE\u3060\u3051\u3067\u57FA\u6E96\u306F\u6E80\u305F\u3055\u308C\u308B", vi: "\u0110\xFAng. Ch\u1EC9 c\u1EA7n 2 h\u1EA1ng m\u1EE5c n\xE0y l\xE0 \u0111\u1EE7 \u0111\xE1p \u1EE9ng ti\xEAu chu\u1EA9n" },
      { ja: "\u8AA4\u308A\u3002\u57FA\u6E96\u306F3\u9805\u76EE\u306E\u307F", vi: "Sai. Ti\xEAu chu\u1EA9n ch\u1EC9 c\xF3 3 h\u1EA1ng m\u1EE5c" },
      { ja: "\u6B63\u3057\u3044\u3002\u9805\u76EE\u6570\u306B\u57FA\u6E96\u306F\u306A\u3044", vi: "\u0110\xFAng. S\u1ED1 l\u01B0\u1EE3ng h\u1EA1ng m\u1EE5c kh\xF4ng c\xF3 quy \u0111\u1ECBnh c\u1EE5 th\u1EC3" }
