    sourceQuoteJa: "\u5EAB\u5185\u306E\u6E29\u5EA6\u3092\u4E0B\u3052\u3001\u96FB\u6E90\u3092\u5207\u3063\u3066\u304B\u3089\u6383\u9664\u3092\u304A\u3053\u306A\u3063\u3066\u304F\u3060\u3055\u3044\u3002",
