    options: ["\u30AF\u30A8\u30F3\u9178", "\u30A8\u30EA\u30BD\u30EB\u30D3\u30F3\u9178\u30CA\u30C8\u30EA\u30A6\u30E0", "\u4E9C\u785D\u9178\u30CA\u30C8\u30EA\u30A6\u30E0", "\u5B89\u606F\u9999\u9178\u30CA\u30C8\u30EA\u30A6\u30E0"],
    correctIndex: 1,
