    options: ["\u305D\u306E\u3053\u3068\u3092\u304A\u5BA2\u69D8\u306B\u4F1D\u3048\u3066\u3044\u308B", "\u3046\u3069\u3093\u306E\u63D0\u4F9B\u3092\u3084\u3081\u3066\u3044\u308B", "\u305D\u3070\u306E\u63D0\u4F9B\u3092\u3084\u3081\u3066\u3044\u308B", "\u7279\u306B\u4F55\u3082\u3057\u3066\u3044\u306A\u3044"],
