    options: ["\u30F4\u30A3\u30FC\u30AC\u30F3", "\u30CF\u30E9\u30FC\u30EB", "\u30B3\u30FC\u30B7\u30E3", "\u30AA\u30FC\u30AC\u30CB\u30C3\u30AF"],
    correctIndex: 1,
