    options: ["\u7A7A\u8ABF\u6A5F\u306E\u96FB\u6E90\u3092\u5165\u308C\u3066\u3044\u308B", "BGM\u3092\u304B\u3051\u3066\u3044\u308B", "\u30C6\u30FC\u30D6\u30EB\u3092\u62ED\u3044\u3066\u3044\u308B", "\u5F93\u696D\u54E1\u306E\u70B9\u547C\u3092\u3068\u3063\u3066\u3044\u308B"],
