    options: ["\u958B\u5E97\u76F4\u5F8C", "\u9589\u5E97\u76F4\u524D", "\u958B\u5E97\uFF13\uFF10\u5206\u524D", "\u55B6\u696D\u4E2D\u3044\u3064\u3067\u3082"],
