function chaptersByPart(partId) {
  return CHAPTERS.filter((c) => c.partId === partId).sort((a, b) => a.order - b.order);
}
function questionsByChapter(chapterId) {
  return QUESTIONS.filter((q) => q.chapterId === chapterId);
}
